import sys
f=sys.argv[1]; s=open(f,encoding='utf-8').read()
def sub(a,b,n=1):
    global s; assert s.count(a)==n,(a[:90],s.count(a)); s=s.replace(a,b)
# ---- day 5 ----
sub("await say(['วันเสาร์\\nผมตื่นมาพร้อมความรู้สึกแปลกๆ ใช้เวลาครู่หนึ่งกว่าจะนึกออกว่ามันคืออะไร','ผมอยากรู้ ว่าวันนี้จะเป็นยังไง']);",
    "await say(['วันเสาร์ ผมตื่นมาพร้อมความรู้สึกแปลกๆ\\nผมอยากรู้ ว่าวันนี้จะเป็นยังไง']);")
sub("await say(['\"สวัสดีครับ\" เสียงเด็กคนนั้น\\n\"ผม… ผู้ป่วยเมื่อวาน\" ผมไม่รู้จะเรียกตัวเองว่าอะไร','\"คุณปู่หลี่! ผมดีใจที่คุณปู่โทรมาครับ\"','\"คืนวันพฤหัส ผมล้มในห้องน้ำ\"\\nพูดทางโทรศัพท์ง่ายกว่า ไม่ต้องเห็นหน้าใคร','\"ขอบคุณที่บอกผมนะครับ เจ็บตรงไหนบ้างครับ\"\\nคำถามแรกของเขา ยังเป็นคำถามนี้']); }",
    "await say(['\"ผม… ผู้ป่วยเมื่อวาน\" \"คุณปู่หลี่! ผมดีใจที่โทรมาครับ\"\\n\"คืนวันพฤหัส ผมล้มในห้องน้ำ\" พูดทางโทรศัพท์ง่ายกว่า ไม่ต้องเห็นหน้าใคร','\"ขอบคุณที่บอกผมนะครับ เจ็บตรงไหนบ้างครับ\"\\nคำถามแรกของเขา ยังเป็นคำถามนี้']); }")
sub("await say(['\"คุณปู่ครับ ผมเองครับ คุณหมอตอบกลับมาแล้วสองท่าน\"','\"ยาแก้แพ้ให้เหลือตัวเดียว แบบที่ไม่ง่วง ยาคลายกล้ามเนื้อเม็ดเหลืองให้หยุดครับ\"\\n\"ส่วนยาเบาหวาน คุณหมอนัดคุณปู่ไปคุยวันพุธ ผมจะไปด้วย\"','วันพุธ ผมมีนัดหาหมออยู่แล้ว\\nแต่เป็นครั้งแรกที่คนที่ไปด้วย จะให้ผมตอบเอง']); cardOff();",
    "await say(['\"คุณปู่ครับ คุณหมอตอบกลับมาแล้วสองท่าน ยาแก้แพ้เหลือตัวเดียว แบบที่ไม่ง่วง เม็ดเหลืองให้หยุดครับ\"\\n\"ยาเบาหวาน คุณหมอนัดคุยวันพุธ ผมจะไปด้วย\"','วันพุธ ผมมีนัดหาหมออยู่แล้ว\\nแต่เป็นครั้งแรกที่คนที่ไปด้วย จะให้ผมตอบเอง']); cardOff();")
sub("await say(['ผมล้างหม้อใบใหญ่ คว่ำไว้\\nแล้วต้มข้าวต้มในหม้อใบเล็ก พอสำหรับวันนี้วันเดียว','ข้าวต้มที่ต้มวันนี้ กินวันนี้\\nรสของมัน คือรสที่ผมลืมไปแล้วว่าเคยชอบ']); cardOff();",
    "await say(['ผมคว่ำหม้อใบใหญ่ แล้วต้มข้าวต้มในหม้อใบเล็ก พอสำหรับวันนี้วันเดียว\\nรสของมัน คือรสที่ผมลืมไปแล้วว่าเคยชอบ']); cardOff();")
sub("await say(['\"แอร์ยี่สิบเจ็ดองศากับพัดลม ค่าไฟวันหนึ่งไม่ถึงค่าข้าวต้มหนึ่งชามครับ\\nคุณปู่จะคันน้อยลง หลับได้ แล้วก็ไม่หน้ามืด\" เด็กคนนั้นคิดเลขให้ผมดูบนสมุด']);",
    "await say(['\"แอร์ยี่สิบเจ็ดองศากับพัดลม ค่าไฟวันหนึ่งไม่ถึงค่าข้าวต้มหนึ่งชามครับ\"\\nเด็กคนนั้นคิดเลขให้ผมดูบนสมุดเมื่อวาน']);")
sub("await say(['สี่โมงเย็น\\nวันนี้ผมไม่พลาดนัด','เจ้าดำมองหน้าผม ผมส่ายหัว\\n\"วันนี้ฟังเฉยๆ เก็บแรงไว้ก่อน\"']); cardOff();",
    "await say(['สี่โมงเย็น วันนี้ผมไม่พลาดนัด\\nเจ้าดำมองหน้าผม ผมส่ายหัว \"วันนี้ฟังเฉยๆ เก็บแรงไว้ก่อน\"']); cardOff();")
sub("await say(['ชั้นสอง\\nต่ำกว่าวันอังคารหนึ่งชั้นเต็มๆ','ผมหยุด เพราะผมเลือกจะหยุด\\nไม่ใช่เพราะโลกหมุน','เจ้าดำดมประตูห้องชั้นสองอยู่นาน\\nมันไม่ได้ดมกลิ่นใหม่มาสองปีแล้ว']);",
    "await say(['ชั้นสอง ต่ำกว่าวันอังคารหนึ่งชั้นเต็มๆ\\nผมหยุด เพราะผมเลือกจะหยุด ไม่ใช่เพราะโลกหมุน']);")
sub("await say(['\"คืนวันพฤหัส ผมล้มในห้องน้ำ\"','เธอไม่ได้ดุ เธอนั่งลงข้างผม จับแขนผมไว้สองมือ\\n\"ทำไมไม่—\" แล้วเธอก็หยุด \"เจ็บตรงไหนบ้างคะ\"','น้องเภสัชคนนั้นสอนเธอด้วย\\nหรือไม่ก็ คนที่ห่วงใครจริงๆ จะถามเหมือนกันหมด']); }",
    "await say(['\"คืนวันพฤหัส ผมล้มในห้องน้ำ\"\\nเธอนั่งลงข้างผม จับแขนผมไว้สองมือ \"ทำไมไม่—\" แล้วเธอก็หยุด \"เจ็บตรงไหนบ้างคะ\"','คนที่ห่วงใครจริงๆ จะถามเหมือนกันหมด']); }")
sub("else await say(['อาเหมยกลับมาพร้อมเกี๊ยวอีกกล่อง\\nเธอไม่ได้พูดเรื่องล้มอีก','เธอแค่เอาแผ่นกันลื่นไปปูในห้องน้ำรวม\\nแล้วติดไฟดวงเล็กไว้ตรงทางเดิน ที่มันเปิดเองตอนมีคนเดินผ่าน']);",
    "else await say(['อาเหมยกลับมาพร้อมเกี๊ยวอีกกล่อง เธอไม่ได้พูดเรื่องล้มอีก\\nเธอแค่เอาแผ่นกันลื่นไปปูในห้องน้ำรวม แล้วติดไฟดวงเล็กไว้ตรงทางเดิน']);")
